t=open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n'); G={}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n',t):
    k,h,w=m[1],int(m[2]),int(m[3])
    rows=[r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k]=[[int(x) for x in r] for r in rows]
def regions(a):
    vals=sorted(set(a.flatten())-{0})
    out={}
    for v in vals:
        m=(a==v); ys,xs=np.where(m)
        r0,r1,c0,c1=ys.min(),ys.max(),xs.min(),xs.max()
        sub=a[r0:r1+1,c0:c1+1]
        out[v]=(m[r0:r1+1,c0:c1+1],sub)
    return out
i1=np.array(G['Demo pair 1 input']); o1=np.array(G['Demo pair 1 output'])
i2=np.array(G['Demo pair 2 input']); o2=np.array(G['Demo pair 2 output'])
ti=np.array(G['Test input'])
for k,inp,outp in [('Demo pair 1',i1,o1),('Demo pair 2',i2,o2)]:
    r=regions(inp)
    print(k,{v:(np.array_equal(m,outp),sub.shape) for v,(m,sub) in r.items()})

